<script setup>
import { computed, ref } from 'vue';
import { Head, Link, useForm } from '@inertiajs/vue3';
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';

const props = defineProps({ notes: { type: Array, default: () => [] }, tags: { type: Array, default: () => [] } });
const editing = ref(null); const tagInput = ref(''); const searchQuery = ref(''); const selectedTag = ref('');
const form = useForm({ title: '', content: '', tags: [], starts_at: '', ends_at: '', all_day: false, calendar_color: '#6366f1' });
const selectedNote = computed(() => props.notes.find(note => note.id === editing.value));
const suggestedTags = computed(() => props.tags.filter(tag => tag.name.toLowerCase().includes(tagInput.value.toLowerCase()) && !form.tags.includes(tag.name)).slice(0, 6));
const tagOptions = computed(() => { const all = [...props.tags, ...props.notes.flatMap(note => note.display_tags || [])]; return [...new Map(all.map(tag => [tag.name.toLowerCase(), tag])).values()].sort((a, b) => a.name.localeCompare(b.name)); });
const filteredNotes = computed(() => { const query = searchQuery.value.trim().toLowerCase(); return props.notes.filter(note => (!query || `${note.title || ''} ${note.content || ''}`.toLowerCase().includes(query)) && (!selectedTag.value || (note.display_tags || []).some(tag => tag.name.toLowerCase() === selectedTag.value.toLowerCase()))); });
function clearFilters() { searchQuery.value = ''; selectedTag.value = ''; }
function newNote() { editing.value = null; form.reset(); }
function edit(note) { editing.value = note.id; form.title = note.title; form.content = note.content || ''; form.tags = (note.display_tags || []).map(tag => tag.name); form.starts_at = note.starts_at?.slice(0, 16) || ''; form.ends_at = note.ends_at?.slice(0, 16) || ''; form.all_day = note.all_day || false; form.calendar_color = note.calendar_color || '#6366f1'; }
function addTag(name = tagInput.value) { const tag = name.trim(); if (tag && !form.tags.includes(tag)) form.tags.push(tag); tagInput.value = ''; }
function save() { if (form.all_day) form.ends_at = ''; const options = { preserveScroll: true, onSuccess: () => newNote() }; editing.value ? form.put(route('notes.update', editing.value), options) : form.post(route('notes.store'), options); }
function remove(note) { if (confirm('Excluir esta anotação?')) useForm({}).delete(route('notes.destroy', note.id)); }
</script>
<template>
    <Head title="Anotações" /><AuthenticatedLayout><div class="max-w-6xl"><div class="flex flex-col gap-4 border-b border-slate-200 pb-6 sm:flex-row sm:items-center sm:justify-between"><div><nav class="mb-1 flex items-center gap-2 text-xs font-medium uppercase tracking-wider text-slate-400"><span>Geral</span><span>/</span><span class="text-slate-600">Anotações</span></nav><h1 class="text-2xl font-bold tracking-tight text-slate-900">Minhas Anotações</h1><p class="mt-1 text-sm text-slate-500">Registre ideias, referências e lembretes em um só lugar.</p></div><button @click="newNote" class="inline-flex items-center justify-center gap-2 rounded-xl bg-slate-900 px-4 py-2.5 text-sm font-medium text-white shadow-sm transition hover:bg-slate-800"><svg class="h-4 w-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg>Nova anotação</button></div><div class="mt-8 grid min-h-[560px] gap-6 lg:grid-cols-[280px_minmax(0,1fr)]"><aside class="flex min-h-0 flex-col rounded-2xl border border-slate-200 bg-white shadow-sm"><div class="border-b border-slate-100 px-4 py-4"><div class="flex items-center justify-between"><h2 class="text-sm font-semibold text-slate-900">Todas as anotações</h2><span class="text-xs text-slate-400">{{ filteredNotes.length }} de {{ notes.length }}</span></div><div class="mt-3 space-y-2"><div class="relative"><input v-model="searchQuery" type="search" placeholder="Buscar título ou descrição" class="w-full rounded-xl border-slate-300 pr-8 text-xs" /><button v-if="searchQuery" @click="searchQuery = ''" type="button" class="absolute right-2 top-1/2 -translate-y-1/2 text-sm text-slate-400" aria-label="Limpar busca">×</button></div><select v-model="selectedTag" class="w-full rounded-xl border-slate-300 text-xs"><option value="">Todas as tags</option><option v-for="tag in tagOptions" :key="tag.name" :value="tag.name">#{{ tag.name }}</option></select><button v-if="searchQuery || selectedTag" @click="clearFilters" type="button" class="text-xs font-medium text-indigo-600">Limpar filtros</button></div></div><div class="max-h-[520px] space-y-1 overflow-y-auto p-2"><button v-for="note in filteredNotes" :key="note.id" @click="edit(note)" class="w-full rounded-xl p-3 text-left transition" :class="editing === note.id ? 'bg-indigo-50' : 'hover:bg-slate-50'"><p class="truncate text-sm font-semibold text-slate-800">{{ note.title }}</p><p class="mt-1 truncate text-xs text-slate-500">{{ note.content || 'Sem conteúdo' }}</p><div class="mt-2 flex flex-wrap gap-1"><span v-for="tag in note.display_tags" :key="tag.name" class="rounded-full px-1.5 py-0.5 text-[10px] font-medium text-white" :style="{ backgroundColor: tag.color }">#{{ tag.name }}</span></div></button><div v-if="!notes.length" class="px-3 py-8 text-center text-xs text-slate-400">Nenhuma anotação criada.</div><div v-else-if="!filteredNotes.length" class="px-3 py-8 text-center text-xs text-slate-400">Nenhuma anotação corresponde aos filtros.</div></div><div class="mt-auto border-t border-slate-100 p-3"><p class="mb-2 text-[11px] font-semibold uppercase tracking-wider text-slate-400">Tags do catálogo</p><div class="flex max-h-24 flex-wrap gap-1 overflow-y-auto"><span v-for="tag in tags" :key="tag.id" class="inline-flex items-center gap-1 rounded-full px-2 py-1 text-[11px] font-medium text-white" :style="{ backgroundColor: tag.color }">#{{ tag.name }}<Link :href="route('notes.tags.destroy', tag.id)" method="delete" as="button" class="opacity-80 hover:opacity-100" title="Remover tag">×</Link></span><span v-if="!tags.length" class="text-xs text-slate-400">As tags aparecerão aqui.</span></div></div></aside><section class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm sm:p-7"><div class="flex items-center justify-between border-b border-slate-100 pb-4"><div><p class="text-xs font-medium uppercase tracking-wider text-slate-400">{{ editing ? 'Editando anotação' : 'Nova anotação' }}</p><h2 class="mt-1 text-lg font-semibold text-slate-900">{{ selectedNote?.title || 'Escreva uma nova ideia' }}</h2></div><div v-if="editing" class="flex items-center gap-1"><button @click="edit(selectedNote)" class="rounded-lg p-1.5 text-slate-400" title="Editar anotação"><svg class="h-4 w-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 20h9"/><path d="M16.5 3.5a2.1 2.1 0 0 1 3 3L8 18l-4 1 1-4Z"/></svg></button><button @click="remove(selectedNote)" class="rounded-lg p-1.5 text-slate-400 hover:bg-rose-50 hover:text-rose-600" title="Excluir anotação"><svg class="h-4 w-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="3 6 5 6 21 6"/><path d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/></svg></button></div></div><form @submit.prevent="save" class="mt-6 space-y-5"><input v-model="form.title" required placeholder="Título da anotação" class="w-full rounded-xl border-slate-300 text-sm font-semibold" /><textarea v-model="form.content" rows="12" placeholder="Comece a escrever..." class="w-full resize-y rounded-xl border-slate-300 text-sm leading-7"></textarea><div><label class="text-xs font-semibold text-slate-500">Tags</label><div class="mt-2 flex gap-2"><input v-model="tagInput" @keydown.enter.prevent="addTag()" placeholder="Digite uma tag" class="min-w-0 flex-1 rounded-xl border-slate-300 text-sm" /><button type="button" @click="addTag()" class="rounded-xl bg-slate-100 px-3 text-sm">Adicionar</button></div><div v-if="suggestedTags.length" class="mt-2 flex flex-wrap gap-1"><button v-for="tag in suggestedTags" :key="tag.id" type="button" @click="addTag(tag.name)" class="rounded-full bg-indigo-50 px-2 py-1 text-xs text-indigo-700">#{{ tag.name }}</button></div><div class="mt-2 flex flex-wrap gap-1"><button v-for="tag in form.tags" :key="tag" type="button" @click="form.tags = form.tags.filter(item => item !== tag)" class="rounded-full bg-slate-800 px-2 py-1 text-xs text-white">#{{ tag }} ×</button></div></div><div class="border-t border-slate-100 pt-5"><p class="text-xs font-semibold uppercase tracking-wider text-slate-400">Adicionar à agenda (opcional)</p><div class="mt-3 grid gap-3 sm:grid-cols-2"><input v-model="form.starts_at" type="datetime-local" class="rounded-xl border-slate-300 text-sm" /><input v-if="!form.all_day" v-model="form.ends_at" type="datetime-local" class="rounded-xl border-slate-300 text-sm" /></div><div class="mt-3 grid gap-3 sm:grid-cols-2"><label class="flex flex-col gap-2 text-xs font-semibold text-slate-500"><span>Dia inteiro</span><span class="inline-flex items-center gap-2 text-sm font-normal text-slate-600"><input v-model="form.all_day" type="checkbox" class="rounded border-slate-300 text-indigo-600" />Sem horário final</span></label><label class="flex flex-col gap-2 text-xs font-semibold text-slate-500"><span>Cor do evento</span><input v-model="form.calendar_color" type="color" class="h-9 w-14 rounded border-slate-300 p-1" /></label></div></div><div class="flex justify-end gap-2 border-t border-slate-100 pt-5"><button v-if="editing" type="button" @click="newNote" class="rounded-xl bg-slate-100 px-4 py-2.5 text-sm font-medium text-slate-700">Cancelar</button><button type="submit" class="rounded-xl bg-slate-900 px-5 py-2.5 text-sm font-medium text-white">Salvar anotação</button></div></form></section></div></div></AuthenticatedLayout>
</template>
